    return deps

def ev(gates, values, sig):
    k, a, b, op = gates[sig]
    if k == \"c0\": return 0
    if k == \"c1\": return 1
    if k == \"not\": return 1 - values[a]
    if k == \"copy\": return values[a]
    if op == \"&\": return values[a] & values[b]
    if op == \"|\": return values[a] | values[b]
    return values[a] ^ values[b]

